/**
 * 니플헤임 그레이딩 테마 데이터.
 *
 * 니플헤임은 **저각 태양이 화면 위 지평선에 걸려 있고 발밑이 가장 깊은 그늘**이다.
 * 아래 값 전부가 그 한 문장의 결과이며, 카르곤(발밑이 용암)의 정확한 반대다:
 *  - 비네트 코어를 **위로** 올려(centerY −0.1) 하단을 더 누른다.
 *  - 차가운 곱연산의 세로 램프를 **아래로 향하게** 뒤집었다(`topStart 0.2 → topEnd 1.0`).
 *    필드 이름은 "상단 램프"지만 계약이 방향을 강제하지 않는다 — 태양이 위에 있는 행성에서
 *    상단을 누르는 것은 서사와 정반대다.
 *  - 스플릿 톤 방향이 **−1**: 하이라이트가 차갑고(설면이 하늘빛을 받는다) 암부가 따뜻하다
 *    (그늘 속 얼음이 지평선의 저각 태양을 되받는 알펜글로). 이 부호가 `+1` 로 박혀 있었다면
 *    단조성 검사가 통째로 뒤집혀 "스플릿이 없다"로 오판됐을 자리다.
 *
 * ## 알파 6개는 독립 슬라이더가 아니다 — 이 행성에서 실제로 푼 배분
 * `gain` 이 하이라이트 색온도를 떠맡으면서 화면 어디서나 0.0443 의 감쇠를 바닥으로 깔고,
 * 남은 예산을 비네트가 먹는다: 모서리 최대 감쇠 ≈ 0.986×0.26 + 0.0347 + 0.0443 ≈ 0.335
 * (상한 0.36) · 중앙 감쇠 ≈ 0.048(잔존율 0.952 ≥ 0.94). 비네트를 0.29 이상으로 올리면
 * 모서리 예산이 터진다 — `validateGradeTheme` 이 격자 전체에서 실제로 계산한다.
 *
 * ## 채널 오버플로가 `shadow` 의 B 를 0 으로 못 박는다
 * `gain` 틴트의 B 가 255(=흰 화소에서 B 손실 0)라, g=1 에서 lift 가 더할 여유가 B 채널에
 * 정확히 0 이다. 그래서 암부 색조는 **B=0 인 순주황**이어야 하고, 그것이 마침 이 행성의
 * 서사(그늘 속 알펜글로)와 정확히 일치한다. 카르곤이 gain R=255 / shadow R=0 으로 등호에
 * 붙었던 것과 같은 경계 사례를 채널만 바꿔 재현한 것이다.
 */

import type { GradeTheme } from '../../contracts/grade.js';

export const NIFLHEIM_GRADE: GradeTheme = {
  themeId: 'niflheim',
  alpha: {
    // 현대 AAA 비네트의 통상 대역(20~40%) 안쪽. 위 예산 계산의 잔여를 전부 여기 넣었다.
    vignette: 0.26,
    /*
     * 알펜글로는 "그늘 속에 남은 온기"라 국소적이고 약해야 한다. 여기를 키우면 화면 하단이
     * 주황으로 물들어 앰버 적탄과 경합한다 — 전역 색온도 분리는 곱연산 gain 의 몫이다.
     */
    warm: 0.03,
    /*
     * 가장자리 **형상**만 담당한다. 틴트가 진한 청색이라 휘도 손실이 0.578 로 커서
     * 알파 0.06 만으로도 모서리에서 0.0347 을 먹는다(예산의 10%).
     */
    cool: 0.06,
    /*
     * 상한에 붙어 있다. 하이라이트를 차갑게 미는 힘이 곧 스플릿 기울기(−0.069)이고,
     * 이 값이 작으면 warmth 교차점이 [0,1] 밖으로 나가 "스플릿이 아니라 전역 캐스트"가 된다.
     */
    gain: 0.3,
    // 위 채널 오버플로 상한(0.3 × 0.2314 = 0.0694)의 절반. 교차점을 화면 중간 명도(≈0.5)에 둔다.
    shadow: 0.0347,
    // 밴딩을 깨는 최소량. 넓은 저채도 설면은 밴딩이 가장 잘 보이는 바닥이라 카르곤과 같게 둔다.
    grain: 0.035,
  },
  /** 코어를 위로 올려 하늘(태양 쪽)을 남기고 발밑을 누른다. `outer` 는 최원거리 모서리(약 1.49)가 거의 최대에 닿는 값. */
  vignette: { centerY: -0.1, inner: 0.65, outer: 1.55 },
  /** 알펜글로는 그늘이 가장 깊은 화면 **하단 1/4** 에서만 올라온다. */
  warm: { startY: 0.45, sideFalloff: 0.45 },
  /** 세로 램프가 아래를 향한다(`topStart < topEnd`) — 태양이 위에 있으므로 그늘은 발밑이다. */
  cool: { topStart: 0.2, topEnd: 1.0, sideStart: 0.62, sideEnd: 1.05 },
  tint: {
    /** 지평선 알펜글로 계열. 저채도로 두어 앰버 적탄과 시각 서명이 겹치지 않게 한다. */
    warm: 0xe8927a,
    /** 깊은 청색 그늘. 하이라이트와 색온도를 가른다. */
    cool: 0x5a6ab0,
    /** 무채에 가깝게, 살짝만 차갑게. */
    grain: 0xb0b8c8,
    /**
     * 하이라이트 청백. B=255 라 흰 화소의 B 손실이 0 이고, 그래서 g=1 에서 오버플로 여유가
     * 정확히 0 인 채로 등호에 붙는다(계약 ⑥의 경계 사례 — 카르곤의 R/B 대칭판).
     * R·G 를 낮춘 만큼이 하이라이트를 차갑게 미는 힘이다.
     */
    gain: 0xc4dcff,
    /**
     * 암부 알펜글로. B=0 은 위 오버플로 조건이 강제한 것이고, 순주황이라 R−B 절편이 최대라
     * 작은 알파로도 스플릿 교차점을 화면 중간 명도에 놓을 수 있다.
     */
    shadow: 0xff6a00,
  },
  /** 설원·빙하 — 하이라이트가 차갑고 암부가 따뜻하다. */
  warmthDirection: -1,
};
